using System.Collections.Immutable;
using Astronomy.MediaFactory.Infrastructure.Production.Narration.Semantics.Resolution.V1.Contracts;
using Astronomy.MediaFactory.Infrastructure.Production.Narration.Semantics.Sources.Adapters.Contracts;
using Astronomy.MediaFactory.Infrastructure.Production.Narration.Semantics.Sources.Contracts;
namespace Astronomy.MediaFactory.Infrastructure.Production.Narration.Semantics.Resolution.V1.Evaluation;
public interface ISemanticCandidateEvaluatorV1 { SemanticCandidateEvaluationV1 Evaluate(SemanticResolutionRequestV1 request, SemanticSourcePolicyV1 policy, SemanticSourceCandidateV1 candidate); }
public sealed class SemanticCandidateEvaluatorV1 : ISemanticCandidateEvaluatorV1
{ public SemanticCandidateEvaluationV1 Evaluate(SemanticResolutionRequestV1 r, SemanticSourcePolicyV1 p, SemanticSourceCandidateV1 c){var issues=new List<string>();var src=p.ApprovedSources.FirstOrDefault(s=>s.SourceId==c.SourceId);bool approved=src is not null&&src.ActiveInV1;if(!c.CapabilityId.Equals(r.CapabilityId))issues.Add("CapabilityMismatch");if(!approved)issues.Add("SourceNotApproved");if(!p.AllowedEvidenceCategories.Contains(c.EvidenceCategory)||!r.AllowedEvidenceCategories.Contains(c.EvidenceCategory))issues.Add("EvidenceCategoryRejected");var min=new[]{r.MinimumEvidenceStrength,p.MinimumEvidenceStrength,src?.MinimumStrength??SemanticEvidenceStrengthV1.Authoritative}.Max();if(c.EvidenceStrength<min)issues.Add("InsufficientEvidence");bool complete=c.Provenance.Length>0&&c.Provenance.All(x=>!string.IsNullOrWhiteSpace(x.SourceId)&&x.Verified);if(!complete)issues.Add("IncompleteProvenance");bool compat=src?.CompatibilityOnly==true;if(compat&&r.Required)issues.Add("CompatibilityOnlyRejected");issues.AddRange(c.ValidationIssues.Where(i=>i.Blocking).Select(i=>i.Code));var eligible=issues.Count==0;var disp=eligible?SemanticCandidateDispositionV1.Eligible:Map(issues[0]);var pri=src?.Priority??int.MaxValue;var comps=new[]{ $"EvidenceStrength={(int)c.EvidenceStrength}",$"SourcePriority={pri}",$"ProvenanceComplete={complete}",$"CompatibilityOnly={compat}",$"Confidence={c.Confidence:0.000}"};return new(Id(c),c.CapabilityId,c.AdapterId,c.SourceId,eligible,disp,c.EvidenceStrength,pri,c.Confidence,Band(c.Confidence),complete,approved,compat,issues.ToImmutableArray(),c.Warnings, new SemanticCandidateScoreV1(comps), eligible?null:string.Join(';',issues));}
 static string Id(SemanticSourceCandidateV1 c)=>$"{c.AdapterId}|{c.SourceId}|{c.CanonicalValue}"; static string Band(decimal c)=>c>=.9m?"High":c>=.7m?"Medium":"Low"; static SemanticCandidateDispositionV1 Map(string s)=>Enum.TryParse<SemanticCandidateDispositionV1>(s,out var d)?d:SemanticCandidateDispositionV1.Invalid; }
